ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_4"] = {
{"r4_sad_lunch_envelope","caller_story_sad",2,8,17,22,2,{"Marty","Knox County Radio Channel, ninety-nine point six, you're on the air, sir - go ahead, please","Caller - Gary","Is this the feed store man? Colburn? You sold me chicken wire in May","Marty","Yes sir, that's me - what can I, what did you want to say?","Caller - Gary","My girl Kelsey was at day camp in West Point Friday - the church camp, by the ball field","Caller - Gary","Every Monday I put her lunch money in an envelope - write her name and the days on it, she thinks it's corny","Caller - Gary","This week's is still on the counter, says Kelsey, Tues through Fri - I forgot to give her Tuesday's","Caller - Gary","So she'd have been short on Tuesday anyhow, is what I keep thinking - like that's the problem","Caller - Gary","If anybody from that camp is listening, she's ten, she's got a green visor - that's all - could you say it once more for me?","Marty","Kelsey, ten years old - green visor, the church camp in West Point","Caller - Gary","Thank you, I'll get off the line now","Marty","(Marty doesn't speak for a while, the carrier hums)"}},
{"r4_sad_library_book","caller_story_sad",2,8,9,21,1,{"Caller - Loretta","I have a question that's going to sound silly, and I apologize for it ahead of time","Marty","Go ahead, ma'am, nothing's silly this week","Caller - Loretta","Is anybody still at the library in Rosewood? The ladies at the desk?","Marty","I don't know, ma'am, I haven't heard anything from Rosewood today","Caller - Loretta","My husband had a book out, a big one about the Civil War, with maps, it was due on the twelfth","Caller - Loretta","Dale paid every bill the day it came, he'd drive across the county to save a dime in late fees","Caller - Loretta","He only got to page two hundred and six, he folded the corner down, they hate when you do that","Caller - Loretta","I've got it in a grocery sack by the door - I just want it to go back where it belongs, if that's alright","Marty","If the library ladies hear this, Mrs. Loretta has your book - it's safe","Marty","(A pause - Marty clears his throat twice)","Marty","We'll go on in a minute"}},
{"r4_sad_thermos_31w","caller_story_sad",2,8,18,23,1,{"Marty","Line's open, you're on ninety-nine six","Caller - Dwayne","Found my daddy's truck this morning on 31-W, south of Muldraugh - door open, keys in it","Marty","Was there any sign of him? I'm sorry, you don't have to answer that","Caller - Dwayne","No sir, just the truck, his thermos was in the cupholder, he fills it every night before his shift","Caller - Dwayne","It was still half full, coffee with too much sugar in it, the way he likes it","Caller - Dwayne","I sat there on the shoulder and drank it - cold, I don't even take sugar","Caller - Dwayne","Just couldn't pour it out on the road - you understand?","Marty","Yes","Caller - Dwayne","I rinsed the thermos out - put it back in the cupholder, left the truck locked so nobody takes it","Caller - Dwayne","Keys are under the mat, Daddy, if you hear this - under the mat","Marty","(There is a long stretch of dead air before Marty speaks again)"}},
{"r4_sad_wedding_cake","caller_story_sad",2,7,10,21,1,{"Caller - Tina","Hi, this is going to be quick, I need to cancel something and I don't have any other way","Marty","All right, ma'am, the floor's yours","Caller - Tina","I'm supposed to get married on the seventeenth, at the Methodist church in Riverside","Caller - Tina","We ordered a cake from Mrs. Albright - three tiers, lemon, because Mike hates chocolate, which I think is crazy","Caller - Tina","Mrs. Albright, if you're listening, you don't have to make it - please don't go out trying to find eggs for it","Marty","Is your, is Mike there with you?","Caller - Tina","He was at his bachelor thing in Louisville Friday night - they went up to see a ball game","Caller - Tina","Anyway, that's all I called for, the deposit's fine, she can keep the deposit","Marty","Mrs. Albright, you heard her - no cake","Marty","(Marty keys the mic, says nothing, and lets go of it)"}},
{"r4_sad_little_league_tie","caller_story_sad",2,8,16,21,1,{"Caller - Roy","Marty, Roy Beam, I coach the nine and ten team in Muldraugh - coached - coach","Marty","Roy, I know you, you bought the lime for the baselines","Caller - Roy","We had a game Friday evening against Brandenburg, top of the fifth, tied three to three - then the sirens started","Caller - Roy","Umpire called it, everybody grabbed their kids and ran for the cars - left the equipment bag in the dugout","Caller - Roy","I drove by today, bag's still there - Scorebook's in it, the Shepherd boy was on second with nobody out","Caller - Roy","He'd have scored, that kid can fly, nobody out, the top of our order coming up","Caller - Roy","I didn't take the book, I just wanted somebody to put it on the air that it was three to three and we had a man on second","Marty","Three to three, man on second, nobody out","Caller - Roy","Suspended game, not a loss - that's all","Marty","(The line goes quiet and Marty lets it stay that way)"}},
{"r4_sad_ultrasound_card","caller_story_sad",2,6,18,23,1,{"Caller - Patsy","I have an appointment card on my fridge for Monday the twelfth, ten-fifteen, Louisville","Marty","The roads to Louisville, ma'am, I don't think you should try - I'm sorry","Caller - Patsy","No, I know, I'm not going, it was the one where they tell you if it's a boy or a girl","Caller - Patsy","We had a bet going - Loser had to paint the nursery, two cans of paint in the carport, pink and blue - we bought both, just to be fair","Caller - Patsy","I just realized today I don't get to find out - not until the baby comes","Caller - Patsy","My mama didn't know with me, she said it was better that way - she said it about everything","Marty","Are you, do you have help out there? Somebody with you?","Caller - Patsy","My neighbor's a nurse's aide - we're alright, I'm just going to have to wait like Mama did","Marty","(Marty takes a breath on the mic and doesn't use it)"}},
{"r4_sad_marty_first_story","caller_story_sad",2,4,21,23,1,{"Marty","We don't have a caller right now, I'll tell you something so the air isn't empty","Marty","Friday morning a boy came in the store for a bag of dog food - twenty-pound bag, he was maybe eleven, paid in quarters and dimes","Marty","He was a quarter short, I told him we'd call it even - he said no sir, and he said he'd bring it Monday","Marty","I don't know his name - blue bicycle, the bag was on the handlebars and he was wobbling all over the road","Marty","I've been sitting here thinking about whether he made it home before it started, and whether the dog got fed","Marty","I don't know why that's the one I can't put down - there were a lot worse things this week","Marty","If you're that young man, you don't owe me the quarter","Marty","(Marty sets the microphone down, the carrier stays on for almost a minute)"}},
{"r4_sad_night_light_hall","caller_story_sad",2,8,21,23,1,{"Marty","It's getting late, if you're still listening, you're not by yourself - go ahead, caller","Caller - Kenny","We had one of those little night lights in the hall - the shell kind that plugs in, for my little brother","Caller - Kenny","Power went Sunday, first night it was dark, he came and got in my bed - said the hall's broke","Caller - Kenny","I'm fourteen, my mom's a trucker - she was out on a run to Memphis","Caller - Kenny","I found a flashlight, I leave it on in the hall now, standing up on the carpet pointing at the ceiling","Caller - Kenny","It uses up a lot of batteries, I took them out of everything, the TV remote - my Walkman, the smoke detector","Caller - Kenny","Is that bad? The smoke detector?","Marty","No, son, you're doing fine - you're doing fine","Caller - Kenny","Okay, he's asleep - I should go turn it off till he wakes up - save them","Marty","(Marty doesn't speak again for some time)"}},
{"r4_hor_baby_monitor","caller_story_horror",2,8,23,4,2,{"Marty","It's late, if you're calling, go ahead - keep your voice down if you need to, I'll hear you","Caller - Angie","We have one of those baby monitors, the receiver picks up other houses sometimes, same channel, I guess","Caller - Angie","The last three nights it's been picking up a nursery - not ours, a woman humming to a baby - the same four notes, around and around","Marty","Do you know which house?","Caller - Angie","The Coles, two down, it has to be - they have a new baby, their house has been dark since Saturday","Caller - Angie","I've been listening every night, it helped, honestly - somebody else was awake and taking care of somebody","Caller - Angie","Tonight about one o'clock the humming stopped in the middle - not at the end, in the middle of a note","Caller - Angie","Then the crib rail, that rattle when you shake the side - it went on a long time - harder","Caller - Angie","Then somebody breathing right on the monitor, right up against it - wet","Caller - Angie","It's still breathing, I've got the receiver in my lap right now, I can't turn it off - I can't make myself turn it off","Marty","Ma'am, turn it off - please - put the batteries somewhere else in the house - please do that for me","Caller - Angie","If I turn it off, I won't know if it's coming down the street","Marty","(Marty's chair creaks, he does not say anything for almost a minute)","Marty","I'm, I'm going to leave the line open, I'm going to go check my own doors - somebody stay on with her"}},
{"r4_hor_deer_stand_ring","caller_story_horror",2,8,22,4,1,{"Caller - Hank","Is this the station? Good, I've been up a tree for two days, I've got a little battery radio up here","Marty","A tree, sir?","Caller - Hank","Deer stand, woods east of Ekron, ladder stand, sixteen feet, I climbed up here Saturday when I heard them coming through","Caller - Hank","First night I heard the leaves - something walking - you know how a deer walks? Stops and starts, this didn't stop, round and round","Caller - Hank","At first light I looked down, there were eleven of them standing around the bottom of my tree in a circle","Caller - Hank","Not making a sound, just faces tipped up - looking at me, mouths open, like baby birds","Caller - Hank","One of them is Jerry Adams, we hunt this stand together - he's wearing the orange hat I gave him","Caller - Hank","He keeps putting his hand on the ladder - not climbing, just resting his hand on the bottom rung, like he remembers what it's for","Marty","Hold on up there - is there, have you got water? Rope?","Caller - Hank","His foot's on the rung now, Marty, his foot's on the first rung","Marty","(The caller's signal drops out - Marty says the name Hank twice and gets nothing back)"}},
{"r4_hor_fallas_lake_shallows","caller_story_horror",2,8,22,4,1,{"Caller - Gordon","I'm on my pontoon boat in the middle of Fallas Lake - been out here two nights, it's safer on the water","Marty","Two nights out there... has it stayed quiet?","Caller - Gordon","It was, tonight the moon's up and I can see the whole shoreline - there's people standing in the shallows","Caller - Gordon","Up to their knees at first, now to their waists - they walked in after dark - hundreds, maybe, all the way around the lake","Caller - Gordon","They're not swimming, they don't swim, they're just walking out slow, toward the boat, and when the bottom drops off they go under","Caller - Gordon","And then the next ones walk in right behind, where the first ones went under","Caller - Gordon","I've got the anchor down on twenty feet of rope. I keep thinking about them on the bottom, still walking","Caller - Gordon","Something touched the anchor line just now, the rope went tight and then loose, tight and then loose","Marty","Pull it up, pull that anchor up, sir, and drift","Caller - Gordon","And if something comes up with it? If there's something on the end?","Marty","(Marty's hand is audible on the desk, tapping, and then it stops)"}},
{"r4_hor_shuffling_count","caller_story_horror",2,8,23,4,1,{"Caller - Ernie","I'm in the ditch under the 31-W overpass south of Muldraugh - in the culvert, I've been here since dusk","Marty","Are you hurt?","Caller - Ernie","No, it's them, they're on the highway above me - walking north, I can hear every step on the concrete","Caller - Ernie","I started counting feet to keep from going crazy, I got to four thousand and then I lost my place","Caller - Ernie","It sounds like a parade with no band, just the feet - sneakers and bare feet and somebody with one high heel","Caller - Ernie","The high heel's the worst - click, drag - click, drag, it's been going by for two hours, it's the same one, it can't be the same one","Marty","Stay put, don't make a sound - they'll pass","Caller - Ernie","There it is again - click, drag","Caller - Ernie","Marty, it's coming down the embankment","Marty","(The line cuts - Marty keeps the channel open and waits, he waits a long time)"}},
{"r5_host_marty_first_night","host",2,4,0,23,3,{"Marty","Good evening, this is Marty Colburn, speaking from March Ridge on ninety-nine point six - I am not with the government or any agency","Marty","I own the feed store in March Ridge, some of you have bought layer mash from me - that's all the qualifications I've got","Marty","This transmitter belongs to the Methodist youth group, they used it for a drive-in Christmas program, it's been in my storeroom under the seed catalogs ever since","Marty","I will read what I know and say plainly what I don't - I'm sorry to tell you the second list is longer","Marty","Please keep your doors locked and your voices low, noise draws them - I saw that with my own eyes, out my own window, this afternoon","Marty","I'll try to come back on at the top of every hour - right now I'm going to go check the back door again"}},
{"r7_mil_route_changed_enroute","military",2,3,8,18,2,{"Roadmaster-3","Freight-1-1, Roadmaster-3, change of route - do not continue to the Muldraugh gate, new release point is the fairgrounds on 31W, over","Freight-1-1","Roadmaster-3, I'm four miles from the gate with eleven vehicles - say reason, over","Roadmaster-3","The gate's closed to wheeled traffic, they're stacking civilian vehicles inside the wire and there's no room to turn a five-ton, over","Freight-1-1","Roger the fairgrounds - Roadmaster-3, does anybody at the fairgrounds know I'm bringing them two water trailers, over?","Roadmaster-3","Negative, nobody at the fairgrounds is on this net, over","Freight-1-1","Then I'm going to roll eleven vehicles into a county fairgrounds full of civilians with nobody expecting me - confirm that's the order, over","Roadmaster-3","That's the order - Freight-1-1, put your best sergeant on the ground before the first truck turns in, over","Freight-1-1","Wilco - Freight-1-1, out"}},
{"r7_mil_convoy_halt_in_the_open","military",2,4,9,20,1,{"Freight-1-1","All Freight stations, this is Freight-1-1, halt, halt, halt - close up and hold what you got, over","Freight-1-4","Freight-1-4, roger halt - what's the holdup, over?","Freight-1-1","The road's full for about three hundred meters, they're walking south in both lanes and along the shoulders, over","Freight-1-4","Freight-1-1, how many, over?","Freight-1-1","Two hundred, maybe more behind the rise, everybody stay in your cab, roll your windows up, and do not sound a horn, over","Freight-1-4","Roger - Freight-1-1, my water trailer's got a slow leak and it's dripping under the truck, over","Freight-1-1","Then it drips - nobody dismounts, we sit here until the road clears, however long that takes, over","Freight-1-4","Wilco - Freight-1-4, out"}},
{"r7_mil_wrong_net_sheriff_channel","military_mistake",2,4,6,23,2,{"Cardinal-1-2","Any Cardinal station, Cardinal-1-2, requesting the location of the fuel point, over","Dispatch","Station calling, this is Knox County, you're on the sheriff's channel, hon","Cardinal-1-2","Say again your station, over?","Dispatch","Knox County Sheriff's dispatch, I've got you loud and clear and so does every scanner from here to Ekron","Cardinal-1-2","Roger - Ma'am, do you know where the fuel point is, over?","Dispatch","The tankers have been parking at the co-op lot on the bypass since yesterday - two of my deputies filled their cars there this morning","Cardinal-1-2","That's more than anybody on my own net has told me all day - thank you, over","Dispatch","You're welcome, and honey, get off my channel, I've got a woman holding on a house fire"}},
{"r7_mil_wrong_net_admin_traffic","military_mistake",2,5,7,22,1,{"Cardinal-3-7","Cardinal Main, Cardinal-3-7, I need forty cots, two hundred cases of water and a five-ton with a working hoist, over","Cardinal Main","Cardinal-3-7, this is the command net, send logistics traffic on the log net, over","Cardinal-3-7","Cardinal Main, I have been on the log net for two hours and nobody answers it, over","Cardinal Main","Cardinal-3-7, that's not my problem to solve on this frequency, over","Cardinal-3-7","Then say who I talk to about forty cots, and I'll go there and I won't bother you again, over","Cardinal Main","Cardinal-3-7, wait out","Cardinal Main","Cardinal-3-7, the log net RTO went to the aid station at noon and he hasn't come back - send your request on this net - one time, send it, over","Cardinal-3-7","Forty cots, two hundred cases of water, one five-ton with a hoist, delivered to the school at Muldraugh - how copy, over?","Cardinal Main","Good copy, it's written down - I can't promise you one cot - Cardinal Main, out"}},
{"r7_mil_relay_two_takes_it","military",2,5,0,23,1,{"Cardinal Main","Cardinal-2-6, Cardinal Main, radio check, over","Cardinal Main","Cardinal-2-6, Cardinal Main, nothing heard, over","Relay Two","Cardinal Main, this is Relay Two on the knob, I have Cardinal-2-6 weak but readable, request permission to relay, over","Cardinal Main","Relay Two, relay, over","Relay Two","Cardinal-2-6, Relay Two relaying for Cardinal Main - Main asks your position and your status on the north barrier, over","Relay Two","Cardinal Main, Relay Two. 2-6 reports he is at the north barrier, he has forty-one civilians at his wire, and he has no water, over","Cardinal Main","Relay Two, ask him how long he has been out of water, over","Relay Two","Cardinal Main, Relay Two, he says since last night - and the civilians know it, over","Cardinal Main","Roger - Relay Two, tell him a water trailer is on the road and I don't know when - word for word, over","Relay Two","Word for word, wilco - Relay Two, out"}},
{"r7_mil_freq_change_left_behind","military_mistake",2,4,6,23,1,{"Cardinal Main","All stations, this is Cardinal Main on the alternate - net call, report in order, over","Cardinal-1-6","Cardinal-1-6, present, over","Cardinal-3-6","Cardinal-3-6, present, over","Cardinal Main","Cardinal-2-6 - Cardinal-2-6, Cardinal Main, over","Cardinal Main","All stations, 2-6 did not make the change, he is sitting on the old frequency calling a net that isn't there, over","Cardinal-1-6","Main, 1-6, I've got a second radio in my track - I'll put it on the old frequency and talk to him from there, over","Cardinal Main","Do it. 1-6, you are now the bridge between him and this net, and you will be until somebody drives out to him, over","Cardinal-1-6","Wilco - Main, how long has he been calling, over?","Cardinal Main","Since the change, about two hours, he's still calling - Cardinal Main, out"}},
{"r7_mil_auth_challenge_at_tcp","military",2,5,0,23,2,{"TCP 5","Station approaching, this is TCP 5, halt where you are and identify, over","Gravel-2-1","TCP 5, this is Gravel-2-1, three vehicles, coming from the armory with generators - requesting passage, over","TCP 5","Gravel-2-1, authenticate Whiskey Delta, over","Gravel-2-1","TCP 5, wait one","Gravel-2-1","TCP 5, I authenticate Foxtrot, over","TCP 5","Negative, that is not the reply on my card - gravel-2-1, stop your vehicles and put your hands on the wheel, over","Gravel-2-1","TCP 5, my card is three days old, I think you're on a new one and I never got it, over","TCP 5","That's likely true and it doesn't change a thing right now - somebody's walking up to your lead vehicle, nobody moves, over","Gravel-2-1","Nobody's moving - TCP 5, my driver is nineteen and he's shaking - tell your man to talk to him before he opens that door, over","TCP 5","He'll talk first, gravel-2-1, stand by"}},
{"r7_mil_medevac_refused_bite","military",2,4,0,23,2,{"Cardinal-2-6","Dustoff Operations, this is Cardinal-2-6 with a nine line, request urgent evacuation, one patient, litter, over","Dustoff Operations","Cardinal-2-6, send lines one through nine, over","Cardinal-2-6","Pickup is the ball field behind the school at Muldraugh - one urgent litter, special equipment none - site is marked with two vehicles and a strobe, over","Dustoff Operations","2-6, say the nature of the wound, over","Cardinal-2-6","Bite wound to the left shoulder, about three hours old - he's conscious, he's my medic, over","Dustoff Operations","Cardinal-2-6, break, request is refused, no aircraft will carry a bite patient, that's a written order from the aviation brigade, over","Cardinal-2-6","Dustoff Operations, say again your last, over","Dustoff Operations","Request refused, no bite patients on aircraft, I'm required to tell you that twice and I've told you twice, over","Cardinal-2-6","Roger - Dustoff Operations, what am I supposed to do with him, over?","Dustoff Operations","Cardinal-2-6, I don't have that answer on any card in this aircraft - I'm sorry - Dustoff Operations, out"}},
{"r7_mil_soldier_from_this_county","military",2,4,6,23,1,{"Cardinal-1-6","Cardinal Main, 1-6, I've got a problem with a soldier and I'd rather ask you than solve it wrong, over","Cardinal Main","Send it, over","Cardinal-1-6","The barrier I'm holding is three hundred meters from one of my soldier's houses - his mother is stood on the porch and she can see him, over","Cardinal Main","1-6, is she asking to pass, over?","Cardinal-1-6","She's not asking anything, she's just stood out there on the porch looking at him and he's been on that barrier nine hours, over","Cardinal Main","Move him, put him on the other side of the road where he faces away, over","Cardinal-1-6","Main, he asked me not to be moved, he said he'd rather see her than wonder, over","Cardinal Main","Then leave him where he is and send somebody to that porch with two cases of water, over","Cardinal-1-6","Wilco, I'll take it myself. 1-6, out"}},
{"r7_mil_barrier_rules_read","military",2,3,5,12,2,{"Cardinal Main","All Cardinal stations, stand by to copy, I am reading the rules for the barriers one time and then your platoon sergeants will read them again to every soldier, over","Cardinal Main","One, you challenge from cover at a hundred meters, you do not stand in the middle of the road, over","Cardinal Main","Two, you warn, then you warn again louder, then you fire into the road surface - then, and only then, into the vehicle, over","Cardinal Main","Three, nobody fires at a vehicle with children visible in it - not for any reason on any order, over","Cardinal Main","Four, anybody who is bleeding gets sat down and looked at before they get told to turn around, over","Cardinal-1-6","Cardinal-1-6, roger all four - Main, what's the rule for a person on foot who just keeps walking, over?","Cardinal Main","1-6, wait one, I'm reading the paragraph again","Cardinal Main","1-6, the rule is you look at them, if it's a person, you go get them, if it isn't, you already know what it is, over","Cardinal-1-6","Roger - Main, my soldiers are going to ask me how to tell the difference at a hundred meters at night, over","Cardinal Main","Then use your lights and let them get closer than you want them to - that's all I've got, and I hate it - Cardinal Main, out"}},
{"r7_nights_no_ambulance_to_send","scanner",2,4,0,5,1,{"Dispatch","Knox 20, I got nothing to send you - Medic 2's out of service with a busted door and Medic 3 is sat at Hardin Memorial","Knox 20","Sat there why?","Dispatch","They won't let her offload, there ain't a bed and there ain't a hallway, she's been in that lot an hour and ten minutes","Knox 20","So if I get a heart attack out on Tanner Road tonight, what am I telling the family?","Dispatch","You tell 'em to put him in the bed of a pickup, Sarge - that's the honest answer and I hate the taste of it","Knox 20","Then that's what we'll do, log it, Bonnie - log that I asked, and log what you had to tell me","Dispatch","It's logged. {time}, both halves of it"}},
{"r7_nights_coroner_nine_ahead","scanner",2,5,1,6,1,{"Knox 26","Dispatch, Knox 26, I need the coroner at 812 Pine Street, female, sixties, in the kitchen, she's been gone a while","Dispatch","Knox 26, the coroner's got nine ahead of you","Knox 26","Nine","Dispatch","Nine, he asked me to ask you can it hold till daylight","Knox 26","It can hold, she ain't going nowhere and there's nobody in this house to be upset about it","Dispatch","Copy - can you get the door shut?","Knox 26","I'll shut the door, dispatch, she's got a jigsaw puzzle on the table about half done - don't put that in the log, I just said it out loud"}},
{"r7_nights_county_barn_pump","scanner",2,4,0,4,1,{"Knox 24","Knox 20, I'm on a quarter tank, the station on 31W's got no power and the county barn pump is padlocked","Knox 20","Who's got the key to the barn?","Knox 24","Road department, fella named Mott - he's home in bed over in Ekron","Knox 20","Then go wake up Mott - take him a pack of cigarettes and he'll be nicer about it","Knox 24","Copy - Knox 20, what do I do when the barn runs dry?","Knox 20","Then you park on a hill in the middle of the county and we call that a patrol - go get the key, 24"}},
{"r7_nights_brought_own_shells","scanner",2,4,21,2,1,{"Knox 20","All Knox units, listen up, the armory's out of buckshot - I got slugs and I got .38, and that's every round we've got","Knox 22","Knox 22, I brought mine from home, box and a half of number four","Knox 26","Knox 26, same, my deer rifle's in my trunk and I don't care a bit who writes it up","Knox 20","Nobody's writing anything up tonight - put tape on what's yours so we can give it back to you","Knox 22","Knox 22, that's real optimistic, Sarge","Knox 20","It's tape, Buckner, costs me nothing to be optimistic with tape"}},
{"r7_nights_channel_two_order","scanner",2,4,19,23,2,{"Knox 20","All units, Knox 20, anything with numbers in it, shelter addresses, or where we're headed next goes on channel 2 from here on","Knox 22","Knox 22, how come?","Knox 20","Because half this county's got a scanner on the kitchen counter and the other half's got one bolted in the truck","Dispatch","He's right, 22, six calls tonight from folks who heard us say the school was open - school's got two hundred people in it now","Knox 20","Two hundred, and when you key up on 2, say nothing you wouldn't want read out loud at church on Sunday","Knox 24","Knox 24, does channel 2 even reach the north end?","Knox 20","No, that's the other problem - Knox 20, out"}},
{"r7_nights_cedar_grove_lot","scanner",2,4,20,1,1,{"Dispatch","Knox 22, Cedar Grove Methodist wants a car in their lot - they got nine families in the fellowship hall and folks knocking at the door","Knox 22","Knox 22, I can sit in that lot, but if a call drops I'm gone, and they need to hear that from me up front","Dispatch","They know, the preacher said he'd take the parking lot and leave the light on over the side door for you","Knox 22","Knox 22 is 10-23 at Cedar Grove - dispatch, how many they got in there now?","Dispatch","Nine families was an hour ago","Knox 22","It's more like twenty, somebody out here's writing names on masking tape and sticking it on the kids' shirts","Dispatch","That's a good idea, 22","Knox 22","Terrible idea and a good one, both at once - Knox 22 standing by"}},
{"r7_nights_dog_in_the_road","scanner",2,5,1,5,1,{"Knox 24","Dispatch, Knox 24 - show me stopped a minute on Tanner Road, there's a dog laid down in the middle of my lane","Dispatch","Is he hit?","Knox 24","No, he's just laid down in the road, collar and all - tag says Roscoe and a phone number that don't ring anymore","Dispatch","What are you gonna do with him, 24?","Knox 24","He's getting in the car, he already got in by himself, actually - he's back where the prisoners ride","Dispatch","Knox 24, you know the sheriff's got a rule about that","Knox 24","The sheriff's got a rule about a lot of things this week - show me 10-8 with one passenger"}},
{"r7_nights_offduty_no_radio","scanner",2,4,22,3,2,{"Dispatch","Knox 20, call from a fella says he's Deputy Ledford, out at 1900 Echo Creek Road, holding two subjects at gunpoint","Knox 20","Ledford's off tonight - is he still on the phone?","Dispatch","He was, the line went dead in the middle of him giving me the address and I can't get it to ring back","Knox 20","Knox 20 en route, all units, that's a deputy out of uniform, no radio, no car, with two men stood in front of him","Knox 22","Knox 22 rolling from Muldraugh - Sarge, what's he look like out of uniform?","Knox 20","Big fella, bald, glasses, he'll be the one hollering that he's a deputy - keep your finger off the trigger till you hear his voice","Knox 22","Copy - Knox 22's coming in from the south so we ain't all three in one line"}},
{"r7_nights_rosewood_asks_county","scanner",2,4,0,5,1,{"Dispatch","Knox 26, Rosewood city's asking for a county car, both their officers are tied up on the same call","Knox 26","Knox 26, copy - what have they got going?","Dispatch","A crowd at the grocery, and a man on the roof of the hardware store who won't come down off it","Knox 26","Which one do they want me on?","Dispatch","The roof, they said the grocery can have whatever it wants tonight","Knox 26","Copy, Knox 26 to the hardware store - dispatch, how long's he been up there?","Dispatch","Since dark, his wife's in the street with a ladder and they won't let her stand it up"}},
{"r7_nights_holding_count_short","scanner",2,4,3,6,1,{"Jail Desk","Knox 20, Jail Desk, my count don't match, board says nineteen, I walked it twice and got seventeen both times","Knox 20","Which two?","Jail Desk","Cell four, two brothers out of March Ridge, booked Saturday on a stolen truck","Knox 20","Doors?","Jail Desk","Doors are shut and locked - Sarge, the sally port's been standing open since two on account of the ambulance","Knox 20","Then they walked out the front like men who read the schedule - put it out with names and what they had on","Jail Desk","I'll have to dig for what they had on, the property sheets are in the box we ain't filed since Friday","Knox 20","Dig for it, and shut the sally port, Fred - shut it now and keep it shut"}},
{"r7_ksp_link_terminal_down","scanner",2,3,8,22,1,{"Trooper 435","Post 4, 435, I need a 10-28 on a Kentucky plate, and I need it quick, this fella's real nervous","Post 4","435, stand by, the LINK terminal's been timing out since about ten o'clock","Trooper 435","Timing out or down?","Post 4","Down, I can't get a return on a plate, a license or a wanted check - Frankfort says the whole state's the same and they'll call me","Trooper 435","So I'm running a stop on a man with no way to know who he is","Post 4","You're running it on what he tells you and what you can see - that's the job today, 435","Trooper 435","Copy, post 4, write down the plate anyway, I want it on paper somewhere besides my hand"}},
{"r7_ksp_old_toll_plaza_camp","scanner",2,4,10,21,2,{"Trooper 406","Post 4, 406, there's people camped at the old toll plaza on the parkway - nine, ten cars pulled in under the canopy","Post 4","406, are they blocking the lanes?","Trooper 406","No, they've done it neat, cars in a half circle, tarps up between them, kids in the shade in the middle","Post 4","What do they want?","Trooper 406","A fella came out to meet me with his hands up before I even got my door shut - he asked if he could keep them there one more night","Post 4","Do they have water?","Trooper 406","They've got a cooler and a case of pop, post 4, I told him yes, if somebody in Frankfort wants to write me up over a toll plaza, let them","Post 4","Nobody in Frankfort is going to write you up today, 406. 10-4"}},
{"r7_ksp_semi_ran_the_block","scanner",2,4,11,22,2,{"Trooper 435","Post 4, 435, I've got a westbound tractor trailer that just went through my roadblock at the ramp - never slowed a bit","Post 4","435, did you get anything off it?","Trooper 435","Red cab, no trailer markings I could read, and the passenger window's busted out - he's running seventy-five, seventy-eight","Post 4","Are you in pursuit?","Trooper 435","I'm behind him, I ain't calling it a pursuit because there's nowhere for him to go and I don't want to be the reason he wrecks","Post 4","That's your call - be advised, the Highway Department has a dump truck across the westbound lanes at the Leitchfield exit","Trooper 435","Then he's going to find it at seventy-eight, post 4, get somebody on the phone and get that dump truck moved","Post 4","Nobody's at that number. 435, back off and let it happen - do not be close to it"}},
{"r7_ksp_family_on_the_shoulder","scanner",2,4,12,20,1,{"Trooper 406","Post 4, 406 - show me stopped at milepost 88, family walking on the shoulder - man, woman, two kids and a wagon","Post 4","406, any vehicle with them?","Trooper 406","Their car's a mile back with the hood up, he says it threw a belt and he ain't got a spare","Post 4","Where are they headed?","Trooper 406","His sister's, in Leitchfield, that's twenty-two miles with a four year old in a garden wagon","Post 4","406, you know I can't authorize a transport with kids in the back of a cruiser","Trooper 406","I know it, post 4, show me out of service for thirty minutes and don't ask me what for","Post 4","406 out of service, thirty minutes, I won't ask"}},
{"r7_ksp_nowhere_to_take_him","scanner",2,4,10,23,1,{"Trooper 406","Post 4, 406, I've got one in custody off the parkway - he's wanted out of Indiana on a warrant, and he told me so himself","Post 4","406, told you himself?","Trooper 406","He said he wanted to be arrested, he said jail's got walls and a door and his car ain't got either","Post 4","Hardin County jail's not taking transfers and the Knox County jail's not taking anybody with anything on their skin","Trooper 406","He's not bit, he's just scared and he's honest about it","Post 4","Stand by, 406","Post 4","406, the jailer says bring him, he says he's got room and he says it's the first easy call he's had all week","Trooper 406","406 copies, en route with one, he says thank you, he asked me to tell you he says thank you"}},
{"r7_trans_bus_down_on_31w","scanner",2,4,12,20,1,{"Transport 1","Jail Desk, Transport 1, the bus is down, we're on the shoulder of 31W about a mile south of the lumber yard","Jail Desk","Transport 1, what happened?","Transport 1","Steam out from under the hood and the temperature gauge in the red - it ain't going anywhere on its own","Jail Desk","How many aboard?","Transport 1","Fourteen and two of us, and it's ninety-eight degrees on a bus with the windows welded shut","Jail Desk","I'll try the county garage","Transport 1","Try them fast, jail Desk, there's a man on a porch across the road watching us with a rifle across his knees - he hasn't moved in ten minutes","Jail Desk","Transport 1, do you want a car?","Transport 1","I want a radiator hose and a bus that runs - but yeah, send a car"}},
{"r7_trans_deputy_asks_the_question","scanner",2,4,14,21,2,{"Transport 1","Knox 3, Transport 1, I'm going to ask you a question and I want you to answer it on the radio","Knox 3","Go ahead","Transport 1","If this bus gets surrounded on this shoulder and we can't drive it, do I unlock the back door or do I not?","Knox 3","Transport 1, wait one","Transport 1","I've waited one twice today, Knox 3","Knox 3","You unlock it, every man on that bus goes out the back and up the road, and you write down every name as he passes you","Transport 1","Copy - Knox 3, say that part again about writing the names","Knox 3","Write every name as he goes by you, that's the order, plain and simple - Knox 3 out"}},
{"r7_trans_count_at_the_gate","scanner",2,4,15,22,1,{"Jail Desk","Transport 1, Jail Desk, you're at the port - give me your count for the log","Transport 1","Thirteen","Jail Desk","Say again your count, Transport 1?","Transport 1","Thirteen, the fourteenth is the man we moved to the front, and he quit breathing about eleven miles back","Jail Desk","Do you have a name?","Transport 1","I've got his name and I've got his property envelope and I've got his glasses in my shirt pocket","Jail Desk","Transport 1, bring the thirteen in and leave him on the bus till the coroner comes","Transport 1","No, I'll carry him in myself and put him somewhere with a door - he rode down there in a chain all day, Jail Desk"}},
{"r7_fire_hydrants_quit","scanner",2,3,9,23,2,{"Engine 32","Dispatch, Engine 32, we're on scene at 240 Ashland, single story, fire through the roof on the back half","Dispatch","Engine 32, copy - do you have a hydrant?","Engine 32","We've got a hydrant and it's giving us nothing - Cap's off, wrench is on, and I've got a dribble running down the curb","Dispatch","Stand by, 32, I'll try the water plant","Engine 32","Don't bother, every hydrant in this end of town's been soft since yesterday afternoon - the plant's on a generator and the generator won't run the high pumps","Dispatch","What do you need, 32?","Engine 32","Every tanker in the county and a creek - get me Tanker 42 and Tanker 44 and somebody with a drop tank","Dispatch","Toning them now, engine 32, be advised, Tanker 44's got a driver and no crew","Engine 32","A driver's all I want, he don't have to get off the truck"}},
{"r7_fire_creek_shuttle","scanner",2,4,10,23,1,{"Car 3","All units on the Ashland Avenue fire, Car 3, we're going to a tanker shuttle, nobody hooks to a hydrant, don't waste the time","Tanker 42","Tanker 42, where am I filling?","Car 3","Echo Creek Road at the low water bridge, engine 33 is setting up there to draft, it's a mile and a quarter each way","Tanker 42","Copy, car 3, that creek's down about a foot and a half from last week","Engine 33","Engine 33 at the bridge, we've got a strainer in the water and we're getting a good prime - send me your tankers one at a time","Car 3","Tanker 42 first, then 44 - keep a hundred yards between you so nobody backs into anybody","Tanker 42","Tanker 42 rolling to the creek, car 3, best I can do is a load every twelve minutes","Car 3","Then that's what the fire gets, twelve minutes at a time"}},
{"r7_fire_let_it_go","scanner",2,4,11,23,2,{"Car 3","Dispatch, Car 3, we're going defensive on 240 Ashland - nobody's going back inside that building","Dispatch","Car 3, copy defensive - is the house occupied?","Car 3","Not anymore, my crew made the front room and the hallway and there's nobody in it to find","Dispatch","Copy","Car 3","Dispatch, put in the report that we let a house burn to the ground because there was no water in the hydrants - use those words","Dispatch","I'll use your words, Car 3","Car 3","Now I'm going to spend what water I've got wetting the two houses beside it, and that's the plan for the rest of the day"}},
{"r7_fire_no_air_bottles","scanner",2,4,8,23,1,{"Engine 21","Car 3, Engine 21, every air bottle on this truck is flat and the cascade at Station 21 won't build past half","Car 3","Engine 21, what's half get you?","Engine 21","About eight minutes on a working fire if the man's calm - nine if he's honest about being scared","Car 3","Then nobody goes in past the front room, eight minutes gets you a hallway and a look","Engine 21","Copy that - car 3, where does a fire department get air in this county now?","Car 3","The welding supply on the bypass has got bottles and a pump, and the man that runs it is Mott's cousin","Engine 21","Then somebody go see Mott's cousin with something to trade - I'll send a fella with cash and a ham"}},
{"r7_ems_out_of_tags","scanner",2,3,7,23,1,{"EMS 1","Dispatch, EMS 1, we're out of triage tags - used the last of the box at the church lot this morning","Dispatch","EMS 1, is there another box anywhere?","EMS 1","There's not, they came from the state and the state ain't sent anything since the seventh","Dispatch","What are you going to use?","EMS 1","Masking tape on the forehead and a marker, one line for go now, two lines for wait, and a circle for the ones we can't do anything for","Dispatch","EMS 1, can you write that down for the other units?","EMS 1","I'll write it on a piece of cardboard and tape it in every rig in the county - one line, two lines, a circle - say it back to me","Dispatch","One line go now, two lines wait, a circle for the ones you can't help"}},
{"r7_ems_two_medics_five_patients","scanner",2,4,10,23,2,{"Medic 2","Dispatch, Medic 2 on scene, 1900 Echo Creek Road, five patients, two of us, one rig","Dispatch","Medic 2, how bad?","Medic 2","One is an eleven year old girl with a broke leg and she's talking to me - two are men who are bit and they know it - two are gone and have been","Dispatch","Copy - Medic 2, what are you taking?","Medic 2","I'm taking the girl","Dispatch","Copy the girl","Medic 2","Dispatch, one of the men asked me to come back for him and I told him yes - I want that on the tape, I told him yes","Dispatch","It's on the tape, Medic 2 - are you going back?","Medic 2","I'm going back, it's forty minutes each way and I'm going back"}},
{"r7_ems_bite_protocol_argument","scanner",2,3,8,23,1,{"Hospital","All EMS units, new standing order from the hospital, any patient with a bite wound gets restrained before transport - both wrists, both ankles","Medic 2","Hospital, Medic 2 - restrained with what? I've got two sets of soft restraints in the whole rig","Hospital","Medic 2, use what you have, tape, webbing, a bedsheet","Medic 2","Hospital, this is a forty year old woman with a bite on her hand who walked out to the driveway to meet me","Hospital","Medic 2, I know what I'm asking","Medic 2","Then say why on the radio, so she can hear it, because she's sitting right here listening and she's asked me twice","Hospital","Because two of my nurses got hurt in the hallway last night by people who were talking one minute and not the next - that's why - tell her I'm sorry","Medic 2","She heard you, she says she'll hold her own hands - she says she'll sit on them and I won't have to do it"}},
{"r7_ems_no_helicopter","scanner",2,4,8,20,1,{"Medic 2","Dispatch, Medic 2, I want the helicopter out of Louisville for a fourteen year old boy with a head injury - can you get them?","Dispatch","Medic 2, stand by, I'll call the hospital's number for the flight desk","Dispatch","Medic 2, the flight desk says they're not coming into Knox County - not to a scene, not to a hospital, not at all","Medic 2","Did they say what the reason was?","Dispatch","They said the county's inside a restricted area and their insurance and the Army both say no - I asked twice","Medic 2","Dispatch, I've got a field right here and a boy who needs to be in Louisville in twenty minutes","Dispatch","I know it, Medic 2","Medic 2","Then I'm driving him - show me en route on the ground and tell the hospital I'm coming whether their door's open or shut"}},
{"exp_ems_triplicate","caller_story_sad",3,21,0,23,1,{"Ada","I used to check every form before we left the hospital","June","Was that part of your job?","Ada","Ambulance paperwork, everybody hated it - me included","June","What made you think about it today?","Ada","A blank carbon copy fell out of my coat","Ada","Three identical pages waiting for somebody to arrive safely","June","You can keep it if you want to","Ada","Already folded it back up, didn't even notice I was doing it"}},
{"exp_store_intercom","caller_joke",3,30,0,23,1,{"Russ","I worked the grocery store intercom, always wanted a bigger audience","June","Careful what you wish for, Russ","Russ","I have a very professional announcement voice","June","Go on, then - nothing misleading","Russ","Attention shoppers, the assistant manager has finally run out of suggestions","June","Was there an assistant manager?","Russ","Me, I was the assistant manager","June","Then at least that announcement came from a reliable source"}},
{"exp_court_date","caller_story_sad",3,30,0,23,1,{"Otto","Had a court date circled on the calendar","June","Nothing you need to explain on the air","Otto","Parking tickets, I was going to argue about a sign","June","You don't sound very angry about it now","Otto","I miss believing the sign was worth arguing about","Otto","Had a whole speech ready, practiced it in the truck","June","Was it a good speech?","Otto","Terrible, judge would've eaten me alive, in the old sense"}},
{"exp_reservist_uniform","military",3,14,0,23,1,{"Soldier","A woman asked me when this would be over","Corporal","What did you say to her?","Soldier","That I didn't know, she looked at the uniform like I'd put it on to trick her","Corporal","People expect the clothes to come with answers","Soldier","Last week I was selling washing machines","Corporal","I remember, you tried selling me one","Soldier","Would've given you a good price","Corporal","Let's get through today, you can be a salesman again after that"}},
{"more_radio_socks_drying","caller_joke",3,3650,20,5,1,{"Pete","Lyle's hung his socks where I sleep","Lyle","Best place for airflow","Pete","He's redirecting the problem into my face","June","Lyle, can't you hang them somewhere else?","Lyle","They don't take up much room","Pete","They take up all the air","June","Gentlemen, I cannot inspect the socks over radio","Pete","Turn it up, you might hear them","Lyle","I'm moving the socks","Pete","Thank you, not over THERE, that's my coat! Lyle!"}},
{"more_radio_somebody_awake","silence",3,3650,0,4,1,{"Caller","Is somebody still there?","June","I'm here","Caller","I don't have anything to report","June","You don't need a report","Caller","Could you say something ordinary?","June","Ordinary - uh... there's ink on my wrist - blue ink, no idea how it got there","Caller","Anything else?","June","The chair squeaks if I lean left, I keep leaning left","Caller","Thanks, that helps for some reason","June","You're welcome - hang on a minute, I'll think of something else"}},
{"more_radio_screen_door","caller_story_sad",3,3650,0,23,1,{"June","What do you miss hearing? Apart from music, I mean - around the house, maybe","Celia","My screen door, had to lift it before you let it close","June","Stuck at the bottom?","Celia","For eleven years, my husband fixed everything except that door","Celia","I asked every spring - eleven springs - can you imagine?","Celia","He'd say, 'House needs something to complain about.' Like that was an answer","June","Sounds like he'd practiced it","Celia","Oh, he had - but, um... a door closed here earlier","Celia","A proper door, and I didn't turn round - ours would've--","Celia","I'd have thought it was him, coming in, you know"}},
{"more_radio_nurse_names","caller_story_sad",3,3650,0,23,1,{"Jean","I used to write names on cups for patients","June","So they didn't get mixed up?","Jean","That too - but, um... there was this man, always checked what I'd written","Jean","I'd set it down and he'd turn the cup round to look","Jean","One day he asked if I could put Mister on it - very polite about it","June","Did you?","Jean","Every time, even the terrible coffee","Jean","MISTER, in big letters, so he could see it without his glasses","Jean","He'd sit up straighter - every time, I don't know why I'm thinking about him tonight","Jean","Still have that marker - keep reaching for it when I pour somebody water"}},
{"king_radio_permission","caller_story_sad",3,3650,0,23,1,{"Ruth","Is it wrong that I had a good afternoon?","June","What happened?","Ruth","Nothing much. Somebody made me laugh","June","That sounds all right to me","Ruth","Then I remembered everything and felt awful","June","You didn't forget anybody by laughing","Ruth","I needed somebody else to say that","June","Then I'm glad you called"}},
{"king_radio_listening_job","host",3,3650,0,23,1,{"June","Some of you apologize for repeating yourselves","June","You don't have to do that","June","I repeat myself for a living, apparently","June","And sometimes the second time is when someone hears you","June","So tell me again, if that's what you need","June","I'll try not to finish it for you","June","I'm not very good at that part","June","I'm trying"}},
{"king_radio_cant_sleep","caller_story_sad",3,3650,0,23,1,{"Owen","I'm tired of being asked whether I slept","June","I won't ask","Owen","They mean well. I know they do","June","What would you rather they asked?","Owen","Whether I want some company","June","Do you?","Owen","Yeah. Just for a bit","June","All right. We can talk about something else"}},
{"king_radio_wrong_laces","caller_joke",3,3650,0,23,1,{"Eddie","Got one boot tied with a shoelace and the other with an apron string","June","Does it stay on?","Eddie","Sure. But I keep feeling underdressed for supper","June","Could've used two apron strings","Eddie","Then I'd have to find another apron","June","You really thought this through","Eddie","Had a lot of time while I was tying the damn thing","June","Well, don't trip over your dinner clothes"}},
{"king_radio_bus_driver","host",3,3650,0,23,1,{"June","A man wrote in about driving a school bus for nineteen years","June","Said he'd remember the children by where they sat, not their names","June","Then one would get taller and he'd have to learn them all over again","June","He asked me not to read out the route","June","I won't. An old route wouldn't tell anybody what's safe now anyway","June","He did want the children to know he remembered them","June","Even the ones who were a pain in the ass","June","Especially those, he says"}},
{"king_radio_bad_directions","instruction",3,3650,0,23,1,{"June","Please put a time on anything you tell us about a road","June","If you saw it yesterday, say yesterday","June","If somebody else told you, say that too","June","I don't want to turn your guess into somebody else's directions","June","A familiar road can still be a bad choice","June","I can't see the road from this microphone","June","Neither can the person listening beside you","June","Tell us what you actually know. Leave room for what you don't"}},
{"knox_meal_joke","caller_joke",3,3650,0,23,1,{"Art","I've discovered a new recipe, cold beans, eaten while glaring at the can","June","What makes it different from your old recipe?","Art","Used to have a chair","June","We'll leave the restaurant review there"}},
{"knox_no_names","instruction",3,3650,0,23,1,{"June","You don't have to give your full name to talk here","June","Please don't tell the entire county exactly where your family sleeps","June","I know a voice can make this feel private - it isn't","June","Some of the people listening won't be the people you wanted to reach"}},
{"knox_dog_bowl","caller_story_sad",3,3650,0,23,1,{"Nora","I still set a bowl down, no dog, just the bowl","June","You don't owe anyone an explanation for that","Nora","I know, just wanted somebody to know he had a name - Otis","June","Otis, we heard you"}},
{"knox_doorknob","caller_story_horror",3,3650,0,23,1,{"Len","What I remember is the doorknob turning, before any banging started","June","You don't have to keep telling it if you don't want to","Len","I never saw who was out there, that's what gets me - I still don't know","Len","I tell myself I was right not to answer, some nights I believe it"}},
{"knox_no_song","music_bridge",3,3650,0,23,1,{"June","I'd play a song here if I had a way to do it","June","You don't want me singing, there are enough problems without that","June","Pick something you used to hear driving home, keep it in your head for a moment","June","I'll give you the quiet to remember it"}},
{"knox_rumor_rule","rumor",3,3650,0,23,1,{"June","I've heard a story about a safe settlement, I don't have a location or a person who has actually been there","June","So I'm not passing along directions, there aren't any I can stand behind","June","Hope is a good thing, sending strangers down a road on nothing isn't","June","Bring us something you saw yourself, and say when you saw it"}},
{"r1_d3_whs_gym_kitchen_door","scanner",3,3,5,12,3,{"Knox 12","Knox 12, 10-33! West Point High School! They're inside the gym!","Dispatch","10-33, all units, West Point High School gym - who can respond?","Knox 4","Knox 4, I'm at the courthouse with my family - leaving now","Knox 20","Knox 20 - Knox 4, stay put, you've got forty people in that basement","Knox 12","They came in the kitchen loading door, somebody propped it open for the breeze, it was so hot in here last night","Knox 12","I'm moving people out the front to the bus lane - there's a school bus sitting here and nobody has the key","Hardin 12","Hardin 12, eight minutes out - Knox 12, I can start a bus without a key - hold on","Knox 12","Hurry, Russ - Bo's in my car, I'm at the doors","Hardin 12","Hardin 12 on scene, going for the bus","Knox 12","Bus is running! Load it! Kids first! Load it!","Knox 12","Bus is full - Hardin 12 is driving it - Knox 12 is staying on the doors till it's out of the lot","Dispatch","Knox 12, get in your car","Knox 12","Soon as the bus clears the lot","Dispatch","Knox 12, Knox County - status","Dispatch","Knox 12, status","Hardin 12","Hardin 12, dispatch, I've got forty-one aboard, headed for the courthouse - Knox 12's car is still in the lot, his dog's in the back seat, the doors are shut"}},
}
